//! 🧪️ Genuine semantic borrows keep original native pages and every denied axis unchanged.
use super::*;
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
struct OriginalLoanJob{payload:RetainedJobPayload,output:RetainedJobPayload,kind:u8,closing:bool}
impl InteractiveJob for OriginalLoanJob{
 fn step<'a>(&'a mut self,cx:&mut StepContext<'_>)->Result<Option<JobOutcomeBorrow<'a>>,OriginalTurnFailure>{match self.kind{0=>JobOutcomeBorrow::admit_yield(cx).map_err(OriginalTurnFailure::from),1=>JobOutcomeBorrow::admit_preview(cx,&self.payload).map_err(OriginalTurnFailure::from),2=>JobOutcomeBorrow::admit_checkpoint(cx,&self.payload,17).map_err(OriginalTurnFailure::from),3=>JobOutcomeBorrow::admit_complete(cx,Some(&self.payload),Some(&self.output)).map_err(OriginalTurnFailure::from),4=>JobOutcomeBorrow::admit_cancelled(cx).map_err(OriginalTurnFailure::from),5=>JobOutcomeBorrow::admit_fault(cx,&self.payload).map_err(OriginalTurnFailure::from),_=>unreachable!()}}

 fn borrow_outcome<'a>(&'a self,original:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>{match original.kind(){JobOutcomeKind::Yield=>original.yielded(),JobOutcomeKind::PreviewReady=>original.preview(&self.payload),JobOutcomeKind::CheckpointReady{..}=>original.checkpoint(&self.payload),JobOutcomeKind::Complete=>original.complete(Some(&self.payload),Some(&self.output)),JobOutcomeKind::Cancelled=>original.cancelled(),JobOutcomeKind::Fault=>original.fault(&self.payload)}}
 fn begin_close(&mut self){self.closing=true;}
 fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{let original=if !self.payload.terminal_is_empty(){&mut self.payload}else{&mut self.output};if original.terminal_is_empty(){return Ok(InteractiveJobCloseStep::Complete{progress:Default::default()})}close_original_retained_step(cx,original.retirement_demands()?,|grant|original.close_step(grant))}
 fn terminal_is_empty(&self)->bool{self.closing&&self.payload.terminal_is_empty()&&self.output.terminal_is_empty()}
}

#[test]
fn original_semantic_outcome_loans_preserve_payload_identity_fixed_grants_and_current_receipts(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let p=&law["policy"];let grant=RetainedCloneGrant{maximum_items:p["items"].as_u64().unwrap()as usize,maximum_copy_bytes:p["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:p["release"].as_u64().unwrap()as usize,maximum_depth:p["depth"].as_u64().unwrap()as usize};let demand=JobOutcomeBorrow::admission_demand();assert!(demand.copy_bytes<4096);assert!(size_of::<StepOutcome>()>4096);semio_framework_trace::record_trace_event_at(OperationId(99101),Generation(1),semio_framework_trace::TraceStage::Cancelled,Some(1));let(_,shared_trace)=observe(||Watchdog::start_at("job.original-semantic-loan",OperationId(99101),Generation(1),InteractiveStage::InteractiveStep,Some(1)).finish_at(Some(2)));eprintln!("[DEBUG] explicit process-shared callback Trace startup before original semantic loan born={} released={}",shared_trace.0,shared_trace.1);assert_eq!(shared_trace.1,0);let(cancel,root_birth)=CancelToken::admit_root(grant).unwrap().unwrap();assert!(root_birth.fits(grant));
 for (kind,variant)in law["variants"].as_array().unwrap().iter().enumerate(){for pages in law["pages"].as_array().unwrap(){let pages=pages.as_u64().unwrap()as usize;let operation=OperationId(99101);let generation=Generation(1);let((mut job,mut ledger),birth)=observe(||{let ledger=Arc::new(JobPayloadOperationLedger::new(operation,generation));let mut payload=RetainedJobPayload::empty(JobPayloadStream::Preview);for i in 0..pages{let mut source=JobPayloadPageSource::new();unsafe{source.storage.as_mut_ptr().cast::<u8>().write(i as u8);}ledger.reserve(JobPayloadStream::Preview,source.allocated_capacity_bytes()).unwrap();payload.pages[i]=Some(JobPayloadPage{source,length:1});payload.page_count+=1;payload.length+=1;}if pages>0{*payload.ledger=Some(Arc::clone(&ledger));}(OriginalLoanJob{payload,output:RetainedJobPayload::empty(JobPayloadStream::CommitOutput),kind:kind as u8,closing:false},Some(ledger))});let payload_pointer=std::ptr::addr_of!(job.payload);let page_pointer=job.payload.page(0).map(|page|page.as_ptr());let mut sequence=0;let mut receipts=RetainedCloneProgress::default();for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let mut actual=RetainedCloneProgress::default();let mut cx=StepContext::with_original_worker_authority(operation,generation,StepBudget::new(1,u64::MAX,denied),&cancel,logical_now_us,ClockStride::new(),&mut sequence,&mut actual,ledger.as_ref().unwrap()).unwrap();let mut verdict=None;let(result,heap)=observe(||drive_step(&mut job,&mut cx,"job.original-semantic-loan",InteractiveStage::InteractiveStep,&mut verdict).unwrap());assert!(result.is_none());assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),RetainedCloneProgress::default());assert_eq!(std::ptr::addr_of!(job.payload),payload_pointer);assert_eq!(job.payload.page(0).map(|page|page.as_ptr()),page_pointer);}
 {let mut cx=StepContext::with_original_worker_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,logical_now_us,ClockStride::new(),&mut sequence,&mut receipts,ledger.as_ref().unwrap()).unwrap();let mut verdict=None;let(outcome,heap)=observe(||drive_step(&mut job,&mut cx,"job.original-semantic-loan",InteractiveStage::InteractiveStep,&mut verdict).unwrap().unwrap());assert_eq!(heap,(0,0));assert_eq!(outcome.admission().progress(),cx.retained_progress());assert_eq!(cx.retained_progress(),RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()});let original=match &outcome{JobOutcomeBorrow::PreviewReady{payload,..}=>Some(*payload),JobOutcomeBorrow::CheckpointReady{state,applied_progress,..}=>{assert_eq!(*applied_progress,17);Some(*state)},JobOutcomeBorrow::Complete{state,output,..}=>{assert!(output.unwrap().terminal_is_empty());*state},JobOutcomeBorrow::Fault{detail,..}=>Some(*detail),_=>None};if let Some(original)=original{assert!(std::ptr::eq(original,payload_pointer));assert_eq!(original.page(0).map(|page|page.as_ptr()),page_pointer);}assert!(verdict.is_some());}assert_eq!(job.payload.page(0).map(|page|page.as_ptr()),page_pointer);job.begin_close();let mut release=birth.1;while !job.terminal_is_empty(){let(step,heap)=observe(||{let mut actual=Default::default();let mut cx=StepContext::with_original_worker_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,logical_now_us,ClockStride::new(),&mut sequence,&mut actual,ledger.as_ref().unwrap()).unwrap();let step=job.close_step(&mut cx).unwrap();assert_eq!(cx.retained_progress(),step.progress());step});assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);release+=heap.1;}let(step,heap)=observe(||crate::component::payload_retirement::close_ledger(&mut ledger,grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);release+=heap.1;let(_,heap)=observe(||drop(job));assert_eq!(heap,(0,0));assert_eq!(birth.0,release);eprintln!("[DEBUG] original semantic loan variant={variant} pages={pages} header={} wholeByValue={} originalPayload={payload_pointer:p} originalPage={page_pointer:?} admittedReceipt={receipts:?} physical={release} terminalDrop0",demand.copy_bytes,size_of::<StepOutcome>());}}
 let mut root=semio_framework_async::CancelTokenRetirement::from_token(cancel);let mut released=0;while !root.terminal_is_empty(){let(step,heap)=observe(||root.close_step(grant).unwrap());assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);released+=heap.1;}assert_eq!(released,root_birth.retained_capacity_bytes);
}
